// ---------------------------------------------------------------- annex A: the questions
body.push(H1(X('Annexe A — Les questions des trois formulaires', 'Appendix A — The questions of the three forms')), P(X('Liste complète des sections et des questions telles que les répondants les reçoivent. Pour les sections en tableau, le répondant ajoute des lignes avec les colonnes indiquées.', 'Full list of the sections and questions as the respondents receive them. For table sections, the respondent adds rows with the columns shown.')));
for (const f of q.forms) {
  body.push(H2(f.name));
  for (const [i, s] of f.sections.entries()) {
    const head = `${i + 1}. ${s.title}${s.origin === 'ai' ? X(' (IA, validée)', ' (AI, validated)') : ''}`;
    if (s.type === 'note') { body.push(P([b(head), ` — ${s.instructions}`], { size: 18, after: 80 })); continue; }
    if (s.columns.length && !s.items.length) { body.push(P([b(head), { text: `${X(' — tableau : ', ' — table: ')}${s.columns.join(' | ')}`, color: C.muted }], { size: 18, after: 80 })); continue; }
    body.push(P([b(head), s.columns.length ? { text: `${X(' — colonnes : ', ' — columns: ')}${s.columns.join(' | ')}`, color: C.muted } : ''], { size: 18, after: 40, keepNext: true }));
    body.push(P(s.items.map((it, k) => `${k + 1}) ${it.label}`).join('   '), { size: 17, after: 100 }));
  }
}

const doc = document({ title: X('CortexSkills — Guide du cas Clinique Al Amal', 'CortexSkills — Al Amal Clinic case guide'), credit: X(`CortexSkills ${version} · Guide utilisateur · Cas Clinique Al Amal`, `CortexSkills ${version} · User Guide · Al Amal Clinic case`), sections: (() => { const secs = [[]]; for (const x of body) { if (x && x.landscapeBlock) { secs.push({ landscape: true, children: x.landscapeBlock }, []); } else secs[secs.length - 1].push(x); } return secs.filter(x => !Array.isArray(x) || x.length); })(), lang: X('fr-FR', 'en-GB') });
fs.mkdirSync(out, { recursive: true });
const file = path.join(out, X('Guide_Utilisateur_Customer_CortexSkills_FR.docx', 'User_Guide_Customer_CortexSkills_EN.docx'));
D.Packer.toBuffer(doc).then(x => { fs.writeFileSync(file, x); console.log(file, (x.length / 1024).toFixed(0) + ' KB'); });
